def transform(g):
    out=[row[:] for row in g]
    H,W=len(g),len(g[0])
    shapes=[(r,c) for r in range(1,H-1) for c in range(1,W-1)
            if all(g[r+dr][c+dc]==3 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)) and g[r][c]==2]
    horiz = any(sum(1 for x in g[r] if x==2)>=W/2 for r in range(H))
    if horiz:
        lines=[r for r in range(H) if sum(1 for x in g[r] if x==2)>=W/2]
    else:
        lines=[c for c in range(W) if sum(1 for r in range(H) if g[r][c]==2)>=H/2]
    def stamp(r,c):
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if (dr,dc)==(0,0): continue
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and out[rr][cc]!=3: out[rr][cc]=1
        if horiz: seqs=[[(r+k,c) for k in range(2,H)] , [(r-k,c) for k in range(2,H)]]
        else:     seqs=[[(r,c+k) for k in range(2,W)] , [(r,c-k) for k in range(2,W)]]
        for seq in seqs:
            for rr,cc in seq:
                if not(0<=rr<H and 0<=cc<W): break
                if out[rr][cc]==0: out[rr][cc]=1
    for r,c in shapes:
        own = c if not horiz else r
        for L in lines:
            if L==own: continue
            rr,cc = (L,c) if horiz else (r,L)
            stamp(rr,cc)
    return out

